-- Production import of the customer-review archive supplied by the site owner.
-- The archive is kept separate from Review because the source contains no
-- authenticated user IDs or deal IDs. No fake User/Deal relationships are created.

CREATE TABLE "LegacyCustomerReview" (
  "id" TEXT NOT NULL PRIMARY KEY,
  "sourceOrder" INTEGER NOT NULL UNIQUE,
  "authorName" TEXT NOT NULL,
  "rating" INTEGER NOT NULL,
  "comment" TEXT NOT NULL,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX "LegacyCustomerReview_sourceOrder_idx" ON "LegacyCustomerReview"("sourceOrder");

