INSERT INTO "LegacyCustomerReview" ("id","sourceOrder","authorName","rating","comment") VALUES ('legacy-review-485',485,'Hamza Kato',3,'The service does what it says. My only minor complaint is that the confirmation emails could be clearer about next steps. Otherwise everything was fine.');
INSERT INTO "LegacyCustomerReview" ("id","sourceOrder","authorName","rating","comment") VALUES ('legacy-review-486',486,'Youssef Lopez',5,'I cannot recommend PESescrow highly enough. As someone who has been burned in direct trades before, this service is a lifesaver. The fact that it''s completely free is mind-blowing given the level of security they provide. AES-256 encryption, two-factor auth, admin verification — it''s enterprise-level security for game account trading. My swap was completed in about 90 minutes and both accounts were exactly as described. 10/10 would use again.');
